"""Shared plumbing of the async relying party and mirrors (generated by ``scripts/gen_async.py``)."""

from __future__ import annotations

import asyncio
import inspect
import json
import time
from collections.abc import Callable
from typing import Any

import httpx

from ._logout import LogoutTokenClaims, LogoutTokenVerifier
from ._verify import DEFAULT_TTL_MS, REFETCH_INTERVAL_MS, JwksCache, _b64url_decode


async def _aw(value: Any) -> Any:
    """Await ``value`` when it is awaitable: stores and callbacks may be sync or async."""
    return await value if inspect.isawaitable(value) else value


class _AsyncLock:
    """An ``asyncio.Lock`` created on first use, so the owner can be built outside a running loop."""

    def __init__(self) -> None:
        self._lock: asyncio.Lock | None = None

    async def __aenter__(self) -> None:
        if self._lock is None:
            self._lock = asyncio.Lock()
        await self._lock.acquire()

    async def __aexit__(self, *exc: Any) -> None:
        assert self._lock is not None
        self._lock.release()


class AsyncJwksCache(JwksCache):
    """:class:`JwksCache` over an :class:`httpx.AsyncClient`: ``await cache.get(kid)``."""

    def __init__(self, url: str, *, http_client: httpx.AsyncClient | None = None, now: Callable[[], int] | None = None,
                 ttl_ms: int = DEFAULT_TTL_MS, refetch_interval_ms: int = REFETCH_INTERVAL_MS) -> None:
        super().__init__(url, now=now, ttl_ms=ttl_ms, refetch_interval_ms=refetch_interval_ms)
        self._ahttp = http_client
        self._alock = _AsyncLock()

    async def get(self, kid: str | None = None) -> dict[str, Any] | None:  # type: ignore[override]
        async with self._alock:
            now = self._now()
            expired = self._cached is None or now - self._fetched_at >= self._ttl_ms
            kid_miss = self._cached is not None and not self._has(kid)
            if not expired and not kid_miss:
                self.last_outcome = "cached"
                return self._cached
            if kid_miss and not expired and now - self._last_attempt_at < self._refetch_interval_ms:
                self.last_outcome = "throttled"
                return self._cached
            self._last_attempt_at = now
            try:
                fetched = await self._afetch()
            except Exception:
                self.last_outcome = "failed"
                return self._cached
            self._cached = fetched
            self._fetched_at = now
            self.last_outcome = "refetched" if kid_miss else "fresh"
            return self._cached

    async def _afetch(self) -> dict[str, Any]:
        owns = self._ahttp is None
        client = self._ahttp or httpx.AsyncClient(timeout=10.0)
        try:
            resp = await client.get(self._url, headers={"accept": "application/json"})
        finally:
            if owns:
                await client.aclose()
        resp.raise_for_status()
        body = resp.json()
        if not isinstance(body, dict) or not isinstance(body.get("keys"), list):
            raise ValueError("atlas: JWKS is malformed")
        return {"keys": list(body["keys"])}


class _Prefetched:
    def __init__(self, keyset: dict[str, Any] | None, outcome: str) -> None:
        self.keyset, self.last_outcome = keyset, outcome

    def get(self, kid: str | None = None) -> dict[str, Any] | None:
        return self.keyset


class AsyncLogoutTokenVerifier:
    """:class:`LogoutTokenVerifier` with an async JWKS fetch: ``claims = await verifier.verify(token)``."""

    def __init__(self, *, issuer: str, client_id: str, jwks_url: str | None = None,
                 jti_seen: Callable[[str], bool] | None = None, http_client: httpx.AsyncClient | None = None,
                 leeway: int = 60, now: Callable[[], int] | None = None) -> None:
        self._args = {"issuer": issuer, "client_id": client_id, "jwks_url": jwks_url, "jti_seen": jti_seen, "leeway": leeway, "now": now}
        LogoutTokenVerifier(**self._args)  # validates the arguments
        self.jwks = AsyncJwksCache(jwks_url or f"{issuer.rstrip('/')}/.well-known/jwks.json", http_client=http_client, now=now)

    async def verify(self, logout_token: str) -> LogoutTokenClaims:
        kid = JwksCache.read_kid(logout_token) if logout_token else None
        keyset = await self.jwks.get(kid)
        sync = LogoutTokenVerifier(**self._args)
        sync.jwks = _Prefetched(keyset, self.jwks.last_outcome)  # type: ignore[assignment]
        return sync.verify(logout_token)
